performance.source:
[Module load: #time];
[Concurrency initializePlatform];
[[|
[System gc]; let started := [16 clockNanos];
[1 to: 500 do: [:i | [[Concurrency field: #platformReady] value]]];
[System println: [[16 clockNanos] - started]];
[System println: [[[Concurrency field: #platformReady] value] == true]];
let failures := [0 asCell];
[System gc]; let facts := [db retainedFactCount]; let started := [16 clockNanos];
[1 to: 20 do: [:i |
  let program := [Concurrency prepareSources: #[]];
  let closed := [program close];
  [[[[closed pollOutcome] at: 0] == #success] ifFalse: [| [failures inc]]]
]];
[System println: [[16 clockNanos] - started]];
[System println: [[failures value] = 0]];
[System println: [[db retainedFactCount] - facts]]
] value]

